  "about_mission_text1": "Calk.KG Кыргызстандын ар бир тургуну үчүн каржылык жана күнүмдүк эсептөөлөрдү жөнөкөй жана жеткиликтүү кылуу үчүн түзүлгөн. Биз ар бир адам өзүнүн каржылык милдеттенмелерин тез жана так эсептөөгө, бюджетти пландоого жана негизделген чечимдерди кабыл алууга мүмкүнчүлүккө ээ болушу керек деп ишенебиз.",
