  "about_our_story": "Биздин тарых",
  "about_story_text1": "Calk.KG долбоору Кыргызстандын тургундарына каржылык эсептөөлөр үчүн жөнөкөй жана ишенимдүү курал керек экендигинен түзүлгөн. Адамдар көп учурда татаал формулалар, эски маалыматтар жана көптөгөн булактардан маалымат издөө менен күрөшүшөт.",
  "about_story_text2": "Биз ар ким тез арада так эсептөөгө алууга мүмкүнчүлүгү бар бирдиктүү платформа түзүүнү чечтик — ипотека, салыктар, коммуналдык төлөмдөр же социалдык жөлөкпулдар болсун. Бардык калькуляторлор Кыргызстандын мыйзамдарына жана өзгөчөлүктөрүнө атайын ыңгайлаштырылган.",
  "about_story_text3": "Бүгүнкү күндө Calk.KG — бул жөн гана калькуляторлордун топтому эмес, ал бүт өлкө боюнча миңдеген үй-бүлөлөр үчүн каржылык чечимдерди кабыл алууда ишенимдүү жардамчы.",
