  "salary_info_title": "Кыргызстанда айлык акы кантип эсептелет",
  "salary_info_text_1": "Кыргызстанда айлык акыны эсептөө КРнын Салык кодекси жана Социалдык фонд жөнүндө мыйзам менен жөнгө салынат. Айлык акы эсептелгенде жумуш берүүчү салыктарды жана социалдык төлөмдөрдү кармап калууга милдеттүү.",
  "salary_info_text_2": "Таза айлык акыны эсептөө формуласы: Таза айлык акы = Гросс - Соцфонд (10%) - Киреше салыгы (10% же 5%). Алгач Соцфондго төлөм кармалат, андан кийин калган суммадан киреше салыгы эсептелет.",
  "salary_info_text_3": "ПВТ резиденттери үчүн киреше салыгынын 5% жеңилдетилген ставкасы колдонулат (стандарттуу 10% ордуна). Бул IT-адистер жана технологиялык компаниялар үчүн олуттуу үнөм.",
