  "customs_faq_title": "Көп берилүүчү суроолор",
  "customs_guide_title": "Кыргызстанда унааларды кедендик тазартуу боюнча толук колдонмо 2026",
  "customs_guide_intro": "Кыргыз Республикасында унааны кедендик тазартуу — ЕАЭС тарифтерин, расмийлөө процедураларын жана актуалдуу ставкаларды түшүнүүнү талап кылган процесс. Биздин калькулятор бардык кедендик төлөмдөрдү так эсептөөгө жардам берет: баждын, жыйымдын, акциздин жана КНСтин.",
  "customs_guide_how_title": "Кедендик төлөмдөрдү эсептөө кантип иштейт",
  "customs_guide_how_text": "Кедендик тазартуунун жалпы наркы үч компоненттен турат: кедендик жыйым (унаанын наркынын 0.4%ы), кедендик баж жана 12% КНС (жеңил унаалар КРда акциз менен салынбайт), ал мурунку төлөмдөрдүн бардыгынын суммасына эсептелет. Эсептөөнүн тактыгы унаанын туура кедендик баалоосунан критикалык көз каранды.",
  "customs_guide_eaeu_title": "Кыргызстан үчүн ЕАЭС тарифтери (2026)",
  "customs_guide_eaeu_text": "2015-жылдан бери Кыргызстан Евразиялык экономикалык биримдиктин (ЕАЭС) мүчөсү болуп саналат, ошондуктан бардык катышуучу өлкөлөр үчүн бирдиктүү кедендик тарифтер колдонулат. Баждын ставкалары эки негизги параметрге жараша болот: унаанын жашына жана кыймылдаткычтын көлөмүнө.",
  "customs_guide_new_cars_title": "Жаңы унаалар (3 жылга чейин)",
  "customs_guide_new_cars_rate": "Баждын базалык ставкасы: кедендик наркынын 15%ы",
  "customs_guide_new_cars_excise": "Акциз кыймылдаткычтын көлөмүнө жараша болот:",
  "customs_excise_0": "1800 см³кө чейин — акциз 0-1%",
  "customs_excise_1": "1801-2300 см³ — акциз салыгы 5%",
  "customs_excise_2": "2301-3000 см³ — акциз салыгы 8%",
  "customs_excise_3": "3000 см³тен ашык — акциз 10%",
  "customs_guide_used_cars_title": "Колдонулган унаалар (3 жылдан ашык)",
