  "customs_guide_components_title": "Кедендик төлөмдөрдүн компоненттери",
  "customs_component_fee": "Кедендик жыйым (0.4%) — документтерди расмийлөө жана кеденинин кызматтары үчүн төлөм",
  "customs_component_duty": "Кедендик баж (15-20%) — бюджетке негизги төлөм",
