  "customs_guide_valuation_title": "Унаанын кедендик баалоосу",
  "customs_valuation_text": "Кедендик нарк кеденинин маалымат базалары боюнча же эсеп-фактура боюнча (эгер ал жогорураак болсо) аныкталат. Баалоонун негизги ыкмалары:",
  "customs_valuation_1": "Сделканын баасы боюнча (сатып алуу-сатуу келишими, эсеп)",
  "customs_valuation_2": "Окшош товарлар боюнча (базардагы окшош унаалар)",
  "customs_valuation_3": "Бирдей товарлар боюнча (ошол эле маркасынын жана жылынын)",
  "customs_valuation_4": "АТК маалымат базалары боюнча (автомобилдик кеден комитети)",
  "customs_faq_q1": "КРда унааны кедендик тазартуу канча турат?",
  "customs_faq_a1": "Кедендик тазартуунун наркы баасына, чыгарылган жылына жана унаанын кыймылдаткыч көлөмүнө жараша болот. Орточо алганда $10,000 турган, 2.0 л кыймылдаткычы бар колдонулган унаа үчүн (3 жылдан ашык) кедендик тазартуу $2,800-3,200 түзөт. Ошол эле наркы бар жаңы унаа үчүн — $2,200-2,600. Так эсептөө үчүн биздин калькуляторду колдонуңуз.",
  "customs_faq_q2": "Кыргызстанда унааны кедендик тазартуу үчүн кандай документтер керек?",
  "customs_faq_a2": "Керектүү документтер: 1) Ээсинин паспорту (жеке адамдар үчүн) же уюштуруучу документтер (юрлица үчүн), 2) жөнөтүлгөн өлкөнүн ПТСи (транспорттук каражаттын паспорту), 3) Сатып алуу-сатуу келишими же эсеп-фактура, 4) Транзиттик номерлер (эгер унаа өз жүрүшү менен алынып келинсе), 5) ЕАЭС ыктык сертификаты (жаңы унаалар үчүн). Ошондой эле кедендик декларацияны толтуруу керек.",
  "customs_faq_q3": "10 жылдан ашык унааны кедендик тазартса болобу?",
  "customs_faq_a3": "Ооба, Кыргызстанда унаанын жашы боюнча чектөөлөр жок. Бирок унаа канчалык эски болсо, салыштырмалуу кедендик төлөмдөр ошончолук жогору. 7-10 жылдан ашык унаалар үчүн кедендик тазартуу базардык наркынын 30-40%ын түзүшү мүмкүн. Ошондой эле эске алыңыз, эски унааларды сатуу кыйынга түшөт жана алар оңдоого көбүрөөк чыгым талап кылат.",
  "customs_faq_q4": "Кедендик тазартуу канча убакыт алат?",
  "customs_faq_a4": "Стандарттык кедендик тазартуу процедурасы туура расмийленген документтердин шартында 1-3 иш күнүн алат. Эгер кошумча экспертиза (VINди текшерүү, кедендик баалоо) талап кылынса — 7-10 күнгө чейин. Процессти тездетүү үчүн кедендик брокерлерге кайрылууну сунуштайбыз, алар расмийлөөнү өздөрүнө 200-500$ кошумча акча үчүн алышат.",
  "customs_faq_q5": "Жеке адамдар жана юрлица үчүн кедендик тазартуу эмнеси менен айырмаланат?",
  "customs_faq_a5": "Тарифтер бирдей, бирок процедура айырмаланат: жеке адамдар жеке колдонуу үчүн жылына 1 унааны кедендик тазарта алышат, юрлица — чектөөсүз. Юрлица кедендик өкүл (брокер) аркылуу иштөөгө милдеттүү, жеке адамдар үчүн бул опциялык. Ошондой эле юрлица жеңилдикчилүү режимдерди колдоно алат (убактылуу кирүү, кайра иштетүү).",
  "customs_faq_q6": "Унааны кедендик тазартпасаң акчаны кайтарып алса болобу?",
  "customs_faq_a6": "Ооба, эгер сиз декларацияны берүүдөн жана жыйымдарды төлөгөндөн кийин кедендик тазартуудан баш тартсаңыз, төлөнгөн каражаттарды (кедендик жыйымдан тышкары) кайтарып алса болот. Буга үчүн 3 жыл ичинде кайтаруу боюнча арызды берүү керек. Унаа кайра чыгарылып же кедендик кампага жайгаштырылышы керек. Кайтаруу 30-60 күн алат.",
  "customs_faq_q7": "КРда электромобилдер үчүн кандай жеңилдиктер бар?",
  "customs_faq_a7": "2024-2027-жылдарда Кыргызстанда жеңилдик иштейт: электромобилдер кедендик баж төлөөдөн бошотулган (15-20%дын ордуна 0%). Бул унаанын наркына жараша $1,500дөн $5,000гө чейин үнөмдөөгө мүмкүндүк берет. Калган төлөмдөр (кедендик жыйым 0.4% жана КНС 12%) калат. Гибриддер жеңилдик албайт: баж 15% (жаңы) / 20% (эски); 0% — таза электромобилдер жана удаалаш гибриддер гана.",
  "customs_faq_q8": "Жүк унаасын же мотоциклди кедендик тазартса болобу?",
  "customs_faq_a8": "Ооба. Жүк унаалары үчүн 15% ставка иштейт (көпчүлүк категориялар үчүн акцизсиз), эсеп толук массасына жараша болот. Мотоциклдер үчүн жөнөкөйлөтүлгөн схема: 10-15% баж + күчтүүлөр үчүн (800 см³тен ашык) акциз 0-5%. Биздин калькуляторду колдонуп, тиешелүү ТК түрүн тандаңыз.",
  "customs_vehicle_type": "Транспорттук каражаттын түрү",
  "customs_vehicle_type_tooltip": "Түр баждын ставкаларына жана жеңилдиктердин болушуна таасир этет",
  "customs_type_passenger": "Жеңил унаа",
  "customs_type_electric": "Электр унаасы",
  "customs_type_hybrid": "Гибрид унаасы",
