  "crop_faq_a1": "Сапаттуу үрөн жана жер семирткичтерди колдонуңуз, агротехниканы сактаңыз, өз убагында сугаруу жана зыянкечтерден коргоо камсыз кылыңыз.",
  "crop_faq_q2": "Кыргызстанда кайсы өсүмдүктөр эң пайдалуу?",
  "crop_faq_a2": "Жашылчалар (помидор, калампир, бадыраң) жогорку рентабелдүүлүк берет, бирок көбүрөөк эмгек жана салым талап кылат. Дан өсүмдүктөрү азыраак пайдалуу, бирок туруктуураак.",
  "crop_faq_q3": "Жер семирткичтерди колдонуу керекпи?",
  "crop_faq_a3": "Ооба, жер семирткичтер жакшы түшүм үчүн абдан маанилүү. Жер семирткичсиз түшүмдүүлүк 30-40%ка төмөндөйт. Сапаттуу жер семирткичтер түшүмдү көбөйтүү менен өзүн актайт.",
  "crop_faq_q4": "Рентабелдүүлүктү кантип эсептөө керек?",
  "crop_faq_a4": "ROI = (Киреше - Чыгым) / Чыгым × 100%. КРда өсүмдүк өстүрүү үчүн 30-50% рентабелдүүлүк жакшы деп эсептелет.",
