  "rent_tip_4": "Жумушка чейин транспорт чыгымдарын эске алыңыз",
  "rent_tip_5": "Кышында коммуналдык төлөмдөр 50-70%га жогору",
  "rent_faq_q1": "Бишкекте квартира ижарасы канча турат?",
  "rent_faq_a1": "Студия 13,000-25,000 сом, 1-бөлмөлүү 17,000-30,000 сом, 2-бөлмөлүү 26,000-45,000 сом, 3-бөлмөлүү 38,000-65,000 сом. Баалар районго жана абалына жараша болот.",
  "rent_faq_q2": "Кепилдик деген эмне жана канча?",
  "rent_faq_a2": "Кепилдик — бул коопсуздук депозити, адатта 2 айлык ижарага барабар. Зыян болбосо, чыгып кеткенде кайтарылат.",
  "rent_faq_q3": "Агенттикке комиссия төлөө керекпи?",
  "rent_faq_a3": "Ооба, адатта айлык ижаранын 50%ы (10,000-30,000 сом). Агенттиксиз lalafo.kg, diesel.kg сайттарынан табууга болот.",
  "rent_faq_q4": "Эмне арзан — ижара же ипотека?",
  "rent_faq_a4": "Бааларга жараша болот. Орточо бааларда ипотека узак мөөнөттө пайдалуураак, бирок чоң баштапкы салым керек. Ижара ыңгайлуу.",
  "rent_faq_q5": "Коммуналдык төлөмдөр ижара наркына киреби?",
  "rent_faq_a5": "Адатта жок. Коммуналдык төлөмдөр (электр, суу, жылытуу) өзүнчө төлөнөт — 3,000-8,000 сом/ай.",
