  "fuel_current_prices": "Бишкектеги отунга актуалдуу баалар (13.03.2026)",
  "fuel_price_note": "Баалар 13.03.2026га Бишкек боюнча актуалдуу; аймактарда 2-5 сом жана газ боюнча андан да көп айырма болушу мүмкүн.",
  "fuel_tips_title": "Отунду кантип үнөмдөө керек?",
  "fuel_tip_1": "Жай тездетүү жана токтоо — 20%ке чейин үнөмдөө",
  "fuel_tip_2": "Дөңгөлөктөрдөгү басымды көзөмөлдөңүз — төмөн басым +10% чыгым",
