  "fuel_tip_5": "Туруктуу ТО — тыгылган фильтр +10-15% чыгым",
  "fuel_tip_6": "Газ бензинден дээрлик 2 эсе арзан — 1-2 жылда актайт",
  "fuel_faq_q1": "Кыргызстанда бензин канча турат?",
  "fuel_faq_a1": "АИ-92 — 79.9 сом/л, АИ-95 — 88.5 сом/л, дизель — 93.9 сом/л, газ — 45.8 сом/л (2026-жыл июлуна карата).",
  "fuel_faq_q2": "Газга өтүү пайдалуубу?",
  "fuel_faq_a2": "Ооба! Газ бензинден дээрлик 2 эсе арзан. ГБОну орнотуу 30,000-50,000 сом турат жана 9,000-15,000 км жүргөндөн кийин өзүн актайт.",
  "fuel_faq_q3": "Отун чыгымын кантип эсептөө керек?",
  "fuel_faq_a3": "Формула: (Литр / Километр) × 100. Мисалы, 500 км жүрүп 40 литр жумшадыңыз: (40 / 500) × 100 = 8 л/100км.",
  "fuel_faq_q4": "Бишкекте кайда арзаныраак май куюуга болот?",
  "fuel_faq_a4": "Ири тармактарда баалар бирдей (Газпромнефть, Tattuu, BP). Көзкарандысыз АЗСтерде арзаныраак, бирок сапаты начараак болушу мүмкүн.",
  "fuel_faq_q5": "Бишкектен Ошко барып келүү канча турат?",
  "fuel_faq_a5": "Аралык 680 км. Седан үчүн (чыгым 8.5 л/100км АИ-95де): 57.8 литр керек, наркы ~5,115 сом бир тарапка.",
  "fuel_faq_q6": "Отун чыгымынын нормалдуу көрсөткүчү кандай?",
  "fuel_faq_a6": "Адатта: малолитражка 6-7 л/100км, седан 8-10, SUV 12-15. Реалдуу чыгым айдоо стилине, жүктөмгө, аба ырайына жана авто абалына көз каранды.",
  "fuel_faq_q7": "Эмне үчүн отун чыгымы көбөйүп кетет?",
  "fuel_faq_a7": "Себептери: шиналарда басым төмөн, ашыкча жүк, агрессивдүү айдоо, фильтр/свечалар эски, форсункалардагы көйгөй.",
  "fuel_faq_q8": "Отун чыгымын кантип так эсептесе болот?",
  "fuel_faq_a8": "Бакты толтуруп, одометрди нөлдөңүз. 200-300 км жүрүп кайра толтуруңуз. Формула: (литр / км) × 100.",
