  "mortgage_down_payment_short": "баштапкы жарна:",
  "mortgage_overpayment_short": "ашыкча төлөм:",
  "mortgage_what_is_content": "бул кыймылсыз мүлктү (квартира, үй, жер участогун) сатып алуу үчүн узак мөөнөттүү кредит, анда сатып алынган үй кредит боюнча күрөө болот. Бул карызды толук төлөп бергенге чейин кыймылсыз мүлк банкта күрөөдө турганын билдирет.",
  "mortgage_what_is_kr_context": "Кыргызстанда ипотека өз үйүн сатып алуунун негизги куралы болуп саналат. Бишкектеги квартиранын орточо наркы 3-8 млн сом түзөт, бул жарандардын көпчүлүгү үчүн накталай сатып алууну мүмкүн эмес кылат.",
  "mortgage_how_works_title": "Иштөө принциби:",
  "mortgage_how_works_content": "Баштапкы жарна киргизесиз (наркынын 10-30%), банк калган сумманы берет жана сиз чектелүү үйдүн ээси боласыз. Кредитти толук төлөп бергенден кийин чектөө алынат.",
  "mortgage_type_new_building": "Биринчи жолу сатылган үйгө ипотека",
  "mortgage_type_new_building_desc": "Куруучудан түздөн-түз жаңы курулуштагы квартираны сатып алуу. Адатта пайдалуураак шарттар, бирок объекттин тапшырылышына убакыт талап кылынат.",
