  "mortgage_requirements_additional_4": "Күрөөнү камсыздандыруу милдеттүү",
  "mortgage_requirements_additional_5": "Башка кредиттер боюнча кечигүүлөр жок",
  "mortgage_documents_title": "Ипотека үчүн керектүү документтер",
  "mortgage_documents_borrower": "📄 Карыз алуучунун документтери:",
  "mortgage_documents_borrower_1": "КР жаранынын паспорту",
  "mortgage_documents_borrower_2": "ИИН (идентификациялык номер)",
