  "deposit_strategy_3_benefit": "Коргоо:",
  "deposit_strategy_3_benefit_text": "Валюталардын курсунун өзгөрүүсүнөн жоготуулардын тобокелдиги азаят, кирешелүүлүк менен туруктуулуктун балансы сакталат.",
