  "single_tax_vs_general_text": "Жалпы режимде таза киреше менен 10% киреше салыгын плюс 12% КНСти төлөйсүз. Бирдиктүү салык жөнөкөй, бирок кирешеден алынат. Эгер чон чыгымдарыңыз болсо (кирешеден 40-60%дан ашык), жалпы режим пайдалуураак болушу мүмкүн.",
