  "single_tax_examples_title": "Бирдиктүү салыкты эсептөө мисалдары",
  "single_tax_example_1_title": "Мисал 1: Бөлүштүк соода",
  "single_tax_example_1_text": "Кийим сатасыз. Айлык киреше — 200 000 сом. Соода үчүн ставка — 4%. Бирдиктүү салык: 200 000 × 4% = 8 000 сом айына.",
  "single_tax_example_2_title": "Мисал 2: Кызматтар",
  "single_tax_example_2_text": "Чач алуучусуз. Айлык киреше — 150 000 сом. Кызматтар үчүн ставка — 6%. Бирдиктүү салык: 150 000 × 6% = 9 000 сом айына.",
  "single_tax_example_3_title": "Мисал 3: Коомдук тамак-аш",
  "single_tax_example_3_text": "Чакан кафеңиз бар. Айлык киреше — 400 000 сом. Ставка — 6%. Бирдиктүү салык: 400 000 × 6% = 24 000 сом айына.",
  "single_tax_faq_title": "Көп берилүүчү суроолор",
  "single_tax_faq_q1": "Ишмердүүлүк түрлөрүн бириктирсе болобу?",
  "single_tax_faq_a1": "Ооба, болот. Бирок ар бир ишмердүүлүк түрү үчүн өз ставкасы колдонулат. Мисалы, товарларды сатсаңыз (4%) жана кызмат көрсөтсөңүз (6%), кирешени өзүнчө эсепке алуу керек.",
  "single_tax_faq_q2": "Киреше 8 млн ашса эмне кылуу керек?",
  "single_tax_faq_a2": "Эгерде жылдык киреше 8 млн сомдон ашса, 10 күндүн ичинде жалпы салык системасына өтүү милдеттүү. Ашкан айдан тартып стандарттык салык ставкалары иштей баштайт.",
  "single_tax_faq_q3": "Соцсалымдарды төлөө керекпи?",
  "single_tax_faq_a3": "Ооба, бирдиктүү салык милдеттүү Социалдык фондго салымдарды жокко чыгарбайт. Бирдиктүү салыкта иштеген жеке ишкерлер бекитилген салым төлөйт — айына болжол менен 1 800 сом (минималдуу айлык акынын 10%).",
  "single_tax_faq_q4": "Кызматкерлерди жалдасаңыз болобу?",
  "single_tax_faq_a4": "Ооба, 10го чейин кызматкерлерди жалдаса болот. Ар бир кызматкер үчүн алардын айлык акысынан киреше салыгын (10%) жана социалдык салымдарды (27.25%) төлөө керек.",
  "single_tax_faq_q5": "Бирдиктүү салыкка кантип өтсө болот?",
  "single_tax_faq_a5": "Жеке ишкерди катоодо дароо бирдиктүү салыкты тандаса болот. Эгерде башка режимде иштесеңиз, салык инспекциясына арыз бериңиз. Өтүү кийинки чейректин башынан мүмкүн.",
  "single_tax_tips_title": "Жеке ишкерлер үчүн пайдалуу кеңештер",
