  "property_guide_title": "Кыргызстанда кыймылсыз мүлккө салык боюнча толук колдонмо 2026",
  "property_guide_intro": "Кыймылсыз мүлккө салык — бул Кыргызстанда жашоо үй-жайына ээлик үчүн жылдык төлөм. Мыйзам жеңилдиктүү аянтты көздөйт, андан салык алынбайт: батирлер үчүн 80 м², үйлөр үчүн 150 м². Биздин калькулятор бардык жеңилдиктерди эске алуу менен салыктын суммасын так эсептөөгө жардам берет.",
  "property_guide_law_title": "Мыйзамдык база 2026",
  "property_guide_law_text": "Кыймылсыз мүлккө салык КРнын Салык кодекси менен жөнгө салынат (339-345-беренелер). 2026-жылдын январынан баштап жаңыланган эрежелер иштейт: максималдуу ставка — 100 сом/м², төлөө мөөнөтү — 1-сентябрга чейин, жеңилдиктүү аянт сакталат (батирлер үчүн 80 м², үйлөр үчүн 150 м²).",
  "property_guide_rates_title": "Аймактар боюнча салык ставкалары 2026",
  "property_rate_bishkek": "Бишкек: 25-40 сом/м² (райондон көз каранды)",
  "property_rate_osh": "Ош: 15-25 сом/м²",
  "property_rate_jalal": "Жалал-Абад: 12-20 сом/м²",
  "property_rate_karakol": "Каракол: 15-22 сом/м²",
  "property_rate_other": "Башка шаарлар: 8-18 сом/м²",
  "property_rate_note": "Так ставкалар жергиликтүү кеңештер тарабынан белгиленет жана жыл сайын өзгөрүшү мүмкүн",
  "property_guide_benefits_title": "Жеңилдиктер жана салык кыскартуулары",
  "property_benefit_1": "Батир: биринчи 80 м² салык салынбайт",
  "property_benefit_2": "Жашоо үйү: биринчи 150 м² салык салынбайт",
  "property_benefit_3": "ЭМС ардагерлери жана 1-2 топтогу майыптар: толук бошотуу",
  "property_benefit_4": "Көп балалуу үй-бүлөлөр (5+ бала): бир объектке бошотуу",
  "property_benefit_5": "Пенсионерлер: жеңилдиктер жок, жалпы негизде төлөшөт",
  "property_guide_calc_title": "Салык кантип эсептелет",
  "property_calc_step1": "1. Техпаспорт боюнча жалпы аянтты аныктайбыз (мисалы, 120 м²)",
  "property_calc_step2": "2. Жеңилдиктүү аянтты алып салабыз (батир үчүн 80 м²)",
  "property_calc_step3": "3. Салык салынуучу аянтты алабыз (120 - 80 = 40 м²)",
  "property_calc_step4": "4. Ставкага көбөйтөбүз (мисалы, 30 сом/м²)",
  "property_calc_step5": "5. Жыйынтык салык: 40 × 30 = 1,200 сом/жылына",
  "property_faq_q1": "Качан салыкты төлөө керек?",
  "property_faq_a1": "Агымдагы жыл үчүн кыймылсыз мүлккө салыкты 1-сентябрга чейин төлөө керек. Мисалы, 2026-жыл үчүн 1-сентябрь 2026-жылга чейин төлөш керек. Мөөнөтү өткөндө карыздын суммасынан күн сайын 0.7% өнөктүк эсептелет.",
  "property_faq_q2": "Жаңы батирге салык төлөө керекпи?",
  "property_faq_a2": "Ооба, салык Мамреестрде менчик укугун каттоодон баштап эсептелип башталат. Эгер батирди жылдын ортосунда каттоосоңуз, салык ээлик кылган айлардын санына пропорционалдуу эсептелет.",
  "property_faq_q3": "Пенсионерлер кыймылсыз мүлккө салык төлөшөбү?",
  "property_faq_a3": "Ооба, пенсионерлер салыкты жалпы негизде төлөшөт. Жеңилдиктер ЭМС ардагерлерине, 1-2 топтогу майыптарга жана көп балалуу үй-бүлөлөргө (5+ бала) гана берилет. Пенсия жашы салыктан бошотуу үчүн негиз эмес.",
  "property_faq_q4": "Квитанция келбесе эмне кылуу керек?",
  "property_faq_a4": "Квитанциянын жоктугу салык төлөөдөн бошотпойт. МММнын сайтындагы (cabinet.salyk.kg) жеке кабинеттен карызды текшериңиз же МММнын аймактык бөлүмүнө кайрылыңыз. ИСНге жараша банктардын мобилдик тиркемелери аркылуу да төлөсөңүз болот.",
  "property_faq_q5": "Дача же гаражга салык салынабы?",
  "property_faq_a5": "Дача жер тилкелериндеги жашоо үйлөрү 150 м² жеңилдик менен жалпы негизде салык салынат. Гараждар жашоого жарабаган жайлар катары жергиликтүү кеңештердин ставкалары боюнча башка мүлккө салык салынат (адатта 5-15 сом/м²).",
  "property_faq_q6": "Бир нече объекттерге жеңилдик алууга болобу?",
  "property_faq_a6": "Жок, салык жеңилдиги (80 м² же 150 м²) ар бир объектке өзүнчө колдонулат. Эгер сизде 120 м² батир жана 200 м² үй болсо, анда батир: (120-80)×ставка, үй: (200-150)×ставка. Жеңилдиктер ар бир объект үчүн жыйынтыкталат.",
  "property_tips_title": "Практикалык кеңештер",
  "property_tip_1": "МММнын жеке кабинетинде жыл сайын 1-августка чейин эсептөөлөрдү текшериңиз",
  "property_tip_2": "Кезектерден качуу үчүн салыкты августтун аягына чейин төлөңүз",
  "property_tip_3": "Төлөө квитанцияларын кеминде 3 жыл сактаңыз",
  "property_tip_4": "Кыймылсыз мүлктү сатууда карыздын жоктугун текшериңиз — болбосо келишим өтпөй калышы мүмкүн",
  "property_tip_5": "Эгер техпаспортто аянт туура эмес көрсөтүлсө, оңдоо үчүн БТИге кайрылыңыз",
  "property_tip_6": "Салыкты банктарда, терминалдар аркылуу, мобилдик тиркемелер жана МММнын сайтында төлөсөңүз болот",
  "property_mistakes_title": "Кеңири таралган каталар",
  "property_mistake_1": "Квитанция келбегендиктен салыкты төлөбөө — каалаганга карабастан төлөө милдеттүүсүз",
  "property_mistake_2": "Пенсионерлер үчүн жеңилдиктерди күтүү — алар жок",
  "property_mistake_3": "Мөөнөтү өткөндө өнөктүктү этибарсыз калтыруу — салык суммасынын 50%на чейин өсүшү мүмкүн",
  "property_mistake_4": "Декларацияда кыймылсыз мүлктүн бардык объекттерин көрсөтпөө — айып пул 5,000-10,000 сом",
  "property_mistake_5": "Жеңилдиктүү аянтты эске албастан салыкты эсептөө — ашыкча төлөө",
