  "water_faq_broken_meter": "Эсептегич бузулса эмне кылуу керек?",
  "water_faq_broken_meter_a": "3 күндүн ичинде суу каналына билдириңиз. Эсептегичти алмаштырганга чейин эсептөө акыркы 6 айдын орточо керектөөсү боюнча жүргүзүлөт. Эсептегичти алмаштыруу үй ээсинин эсебинен жүргүзүлөт. Наркы: 2000-4000 сом (эсептегич + орнотуу + мөөрлөө).",
