  "water_faq_verification_a": "Муздак суу: ар 6 жылда. Ысык суу: ар 4 жылда. Кийинки текшерүү датасы эсептегичтин паспортунда көрсөтүлгөн. Текшерүүнү аккредиттелген уюмдар жүргүзөт. Наркы: 500-1000 сом. Өз убагында текшербесе эсептегич бузулган деп эсептелет.",
  "water_faq_benefits": "Суу үчүн жеңилдиктерди ала аламбы?",
  "water_faq_benefits_a": "Ооба, жеңилдиктер берилет: ЭМСтин ардагерлерине жана эмгек ардагерлерине (50% жеңилдик), 1-2 топтогу майыптарга (30-50%), көп балалуу үй-бүлөлөргө (кээ бир аймактарда). Жеңилдик алуу үчүн жашаган жериңиз боюнча социалдык коргоо бөлүмүнө справка менен, андан кийин суу каналына кайрылыңыз.",
  "water_faq_disconnect": "Төлөбөгөндүгү үчүн сууну өчүрүшү мүмкүнбү?",
  "water_faq_disconnect_a": "Ооба, 2-3 ай карыз болгондо. Өчүрүүдөн мурун 10 күн мурда жазуу жүзүндөгү эскертүү жөнөтүлөт. Өзгөчөлүктөр: 3 жашка чейинки балдары бар үй-бүлөлөр, 1-топтогу майыптар, карантин мезгилинде. Сууну кайра кошуу үчүн карызды төлөп, кайра туташтыруу үчүн төлөңүз (адатта 200-500 сом).",
  "water_faq_quality": "Эмне үчүн суу булуттуу же жыты бар?",
  "water_faq_quality_a": "Себептер: суу түтүктөрүн профилактикалоо/оңдоо (убактылуу), үйдөгү эски түтүктөр (дат), хлордун жогорулатылган мазмуну (зарарсыздандыруу). Чечимдер: фильтрлерди орнотуңуз, сууну 2-3 саатка коюп коюңуз, сапатын текшерүү үчүн суу каналына кайрылыңыз. Кырдаалдык линия: 150 (Бишкек).",
