  "water_tariff_formation_text": "Кыргызстанда муздак суу менен камсыздоо жана канализация тарифтерин Суу менен камсыздоо жана канализация департаменти менен макулдашуу менен жергиликтүү бийлик органдары белгилейт. Алар аймакка, керектөөчүнүн түрүнө жараша болот жана сууну чыгаруу, тазалоо, ташуу, ошондой эле канализация тармактарын иштетүү чыгымдарын камтыйт.",
