  "social_fund_tip_1": "Социалдык салымдарды ар айда келерки айдын 20-күнүнө чейин төлөө зарыл",
  "social_fund_tip_2": "Өз убагында төлөбөсөңүз, төлөнбөгөн суммадан ар күн үчүн 0.05% өлчөмүндө айып пул эсептелет",
  "social_fund_tip_3": "Соцфондго салымдар бардык кызматкерлерге, анын ичинде чет элдик жарандарга да эсептелүүгө тийиш",
  "social_fund_tip_4": "Салымдарды эсептөө үчүн максималдуу база республика боюнча орточо эмгек акынын 10 эсе өлчөмүн түзөт",
  "social_fund_tip_5": "Эсептөөлөрдүн жана төлөөлөрдүн так эсебин алып туруңуз — бул текшерүүдө айып пулдардан сактайт",
