  "social_fund_link_gnpf_desc": "Топтомдук бөлүк жөнүндө маалымат",
  "social_fund_faq_title": "Көп берилүүчү суроолор",
  "social_fund_guide_title": "КРда социалдык салымдар боюнча толук колдонмо 2026",
  "social_fund_guide_intro": "Социалдык салымдар - КРнын Соцфондуна жумуш берүүчүлөрдүн жана кызматкерлердин милдеттүү төлөмдөрү. Пенсияларды, оорукана баракчаларды, декреттик акыларды камсыз кылат. Жумуш берүүчүнүн ставкасы 17.25%, кызматкердин 10%.",
  "social_fund_faq_q1": "Соцфондго салымдарды ким төлөйт?",
  "social_fund_faq_a1": "Жумуш берүүчү маянадан 17.25% төлөйт (жумуш берүүчүнүн эсебинен) + кызматкердин маянасынан 10% кармап, которот. Жалпысынан маянадан 27.25% Соцфондго барат.",
  "social_fund_faq_q2": "Качанга чейин төлөө керек?",
  "social_fund_faq_a2": "Учурдагы ай үчүн социалдык салымдарды келерки айдын 20-күнүнө чейин төлөө керек. Мисалы, январь үчүн - 20-февралга чейин. Мөөнөтү өткөндө - өнөктүк күнүнө 0.05%.",
  "social_fund_faq_q3": "Салымдар үчүн максималдуу база барбы?",
  "social_fund_faq_a3": "Ооба, салымдар КР боюнча орточо маянанын 10 эсе өлчөмүнө чейинки маянадан эсептелет (2026-жылы болжол менен 300,000 сом). Бул чектен жогору суммадан салымдар эсептелбейт.",
  "social_fund_tip_employer": "Жумуш берүүчүлөр: салымдарды өз убагында төлөңүз - айып пулдар карыздын суммасынын 100%на жетиши мүмкүн",
  "social_fund_tip_worker": "Кызматкерлер: жумуш берүүчү сиздин салымдарыңызды которгонун текшериңиз (жеке кабинет socfond.kg)",
  "social_fund_tip_ip": "Кызматкерсиз ЖИ: пенсия стажы үчүн ыктыярдуу салымдарды төлөй аласыз (минимум 1,500 сом/ай)",
  "pension_calc_title": "Пенсия калькулятору",
  "pension_calc_subtitle": "КР системасы боюнча бардык компоненттердин детализациясы менен келечектеги пенсияны эсептөө",
  "pension_calc_description": "👴 Кыргызстанда келечектеги пенсияны деталдуу эсептөө! Эмгек стажын, маянаны, негизги жана камсыздандыруу бөлүктөрүн эске алабыз. Бардык компоненттердин детализациясы менен кадам-кадам калькулятор.",
