  "pension_example_base": "Негизги пенсия:",
  "pension_example_base_amount": "4,000 сом",
  "pension_example_total": "Жалпы пенсия:",
  "pension_example_total_amount": "28,561 сом/ай",
  "pension_important_note": "Маанилүү:",
  "pension_important_text": "Пенсиянын фактылык өлчөмү көптөгөн факторлорго көз каранды: инфляция, ТПФтин кирешелүүлүгү, мыйзамдагы өзгөрүүлөр. Калькулятор болжолдуу прогноз берет.",
  "pension_npf_desc": "Кыргызстанда Финкөзөмөлдүн лицензиясы бар эки мамлекеттик эмес топтомдук пенсиялык фонд иштейт. Топтомдоо бөлүгүн тандалган фондго которсоңуз же мамлекеттик фонддо (Социалдык фонддун алдындагы ТПФ) калтырсаңыз болот — жылына 1 жолудан көп эмес.",
  "pension_npf_kyrgyzstan": "ТПФ \"Кыргызстан\"",
  "pension_npf_salym": "ТПФ \"Дордой Салым\"",
  "pension_npf_registry": "ТПФтин актуалдуу реестри жана лицензиялары — Финкөзөмөлдүн сайтында:",
  "pension_npf_check": "Топтомдорду кантип текшерүүгө болот:",
  "pension_npf_check_text": "ТПФтин сайтында же мобилдик колдонмосунда катталыңыз. Ал жерде көрөсүз: топтомдордун суммасын, айлык салымдарды, кирешелүүлүк тарыхын.",
  "pension_faq_withdraw": "Пенсиялык топтомдорду мөөнөтүнөн мурда алууга болобу?",
  "pension_faq_withdraw_answer": "Жок, топтомдук бөлүктү мөөнөтүнөн мурда алуу мүмкүн эмес. Өзгөчөлүктөр: 1) Чет өлкөгө туруктуу жашоого көчүү (баарын алууга болот). 2) 1-2 топтун майыптыгы (мөөнөтүнөн мурда пенсия). 3) Салымчы каза болгон учурда",
  "pension_faq_unofficial": "Расмий эмес иштесем эмне болот?",
  "pension_faq_unofficial_answer": "Расмий эмгекке албастан жумуш берүүчү ТПФга жана Соцфондго салымдарды жасабайт. Бул билдирет: 1) Топтомдук бөлүгү түзүлбөйт. 2) Стаж жүрбөйт. 3) Келечекте минималдуу негизги пенсия гана аласыз (3500-4000 сом). Сунуш: расмий рөөмдөөнү талап кылыңыз же ЖИ катары каттоодон өтүп, өзүңүз салымдарды төлөңүз.",
  "pension_faq_voluntary": "ТПФга ыктыярдуу салымдарды жасоого болобу?",
  "pension_faq_voluntary_answer": "Ооба! Каалаган жаран келечектеги пенсияны көбөйтүү үчүн ТПФга ыктыярдуу салымдарды жаса алат. Минималдуу салым: 500 сомдон. Артыкчылыктар: 1) Топтомдук бөлүктү көбөйтөсүз. 2) Салымдар ТПФ тарабынан инвестицияланат (кирешелүүлүк жылына 7-9%). 3) Салымдын суммасынын 10% салык кайтарылышы (киреше салыгын кайтарып алууга болот). Каалаган ТПФда же онлайн ресмилөөгө болот.",
  "pension_faq_entrepreneur": "ЖИ жана патент ээлери салымдарды кантип төлөшөт?",
  "pension_faq_entrepreneur_answer": "ЖИ киреше көз карандысыз Соцфондго туруктуу салымдарды төлөйт: 2026-жылы ~1200 сом/ай (14,400 сом/жыл). Алардын бир бөлүгү пенсиянын түзүлүшүнө өтөт. Патент боюнча: салымдар патенттин баасына кирет. Келечектеги пенсияны көбөйтүү үчүн ТПФга ыктыярдуу салымдарды жасаңыз (минимум 500 сом/ай).",
  "pension_faq_solidarity": "Солидардык компонент деген эмне?",
  "pension_faq_solidarity_answer": "Солидардык компонент - бул жумуш берүүчүнүн салымдарынын бир бөлүгү (17,25%), ал Соцфонддун жалпы \"казанына\" өтөт жана учурдагы пенсияларды, жөлөкпулдарды, оору акыларын төлөөгө бөлүштүрүлөт. Бул акча сиздин жеке эсебиңизде топтолбойт. Сиздин жеке топтомуңуз жумуш берүүчү ТПФга которгон 10%дан гана түзүлөт. Тактап айтканда, бул 10% сиздин",
  "pension_faq_solidarity_answer_2": "ТПФдагы жеке эсебиңизде.",
  "pension_faq_apply": "Пенсияны кантип ресмилөөгө болот?",
  "pension_faq_apply_timeline": "Пенсиялык жашка чейин 6 ай калганда:",
  "pension_faq_apply_step1": "Документтерди чогултуңуз: паспорт, эмгек китепчеси, айлык акы жөнүндө справкалар",
  "pension_faq_apply_step2": "Жашаган жериңиздеги Социалдык фондго кайрылыңыз",
  "pension_faq_apply_step3": "Арыз жазыңыз (sfkr.kg порталы аркылуу онлайн болот)",
