  "pension_faq_apply_step5": "Алуу ыкмасын көрсөтүңүз: картага, почта аркылуу, банк аркылуу",
  "pension_faq_apply_phone": "Соцфонддун тез жардам линиясынын телефону:",
  "pension_faq_apply_phone_number": "150 (акысыз)",
  "pension_increase_tip1": "1. \"ак\" айлык акы менен расмий иштегиле",
  "pension_increase_tip1_desc": "Пенсиядагы айырма: 4000 сом (стажсыз) vs 20,000+ сом (топтомдор менен).",
  "pension_increase_tip2": "2. Ыктыярдуу салымдарды жасагыла",
  "pension_increase_tip2_desc": "20-30 жылдын ичинде айына кошумча 2000-3000 сом да пенсияга олуттуу кошумча берет (айына кошумча 15,000-30,000 сом).",
  "pension_increase_tip3": "3. Жогорку кирешелүүлүгү бар ТПФ тандагыла",
  "pension_increase_tip3_desc": "30 жылдын ичинде жылына 1-2% кирешелүүлүктөгү айырма жүз миңдеген сомдорго айырма берет. Жыл сайын Социалдык фонддун сайтында ТПФтардын кирешелүүлүгүн салыштырыңыз.",
  "pension_increase_tip4": "4. Салымдарыңызды көзөмөлдөгүлө",
  "pension_increase_tip4_desc": "ТПФтин жеке кабинети аркылуу жылына кеминде бир жолу салымдардын түшүшүн текшериңиз. Жумуш берүүчүнүн каталары он миңдеген сомдорго түшүргө мүмкүн.",
