  "salary_calc_description": "💰 Кыргызстанда \"колго\" айлык акынын так эсептөөсү! Киреше салыгын (10% же ПВТ үчүн 5%) жана Соцфондго төлөмдөрдү (10%) эсептегиле. Тез, акысыз, бардык кемитүүлөрдүн детализациясы менен.",
