  "auto_loan_faq_q5": "Автокредитти канча мөөнөткө алуу жакшы?",
  "auto_loan_faq_a5": "Оптималдуу 2-3 жыл (24-36 ай). Бул ыңгайлуу айлык төлөм жана акылга сыярлык ашыкча төлөөнүн ортосундагы тең салмактуулук. 5 жылга алуу пайдасыз – ашыкча төлөө өтө көп болот, андан тышкары унаа ушул убакыттын ичинде наркынан көп түшөт.",
