  "zakat_religious_notice_title": "🕌 ДИНИЙ БИЛДИРҮҮ",
  "zakat_religious_notice_text1": "<strong>Бул калькулятор</strong> закятты алдын ала эсептөө үчүн <strong>көмөкчү куралдар</strong>. Ал жалпы кабыл алынган ислам принциптерине негизделген жана бардык жеке шарттарды эске албашы мүмкүн.",
  "zakat_religious_notice_text2": "Закят — бул Аллах белгилеген <strong>мусулмандын диний милдети</strong>. <strong>Так диний көрсөтмөлөрдү</strong> жана татаал учурларды түшүндүрүүнү <strong>квалификациялуу диний окумуштуулардан</strong> сураңыз.",
  "zakat_religious_notice_text3": "<strong>КРдагы байланыштар:</strong> Кыргыз Республикасынын мусулмандарынын Диний башкармалыгы же сиздин жергиликтүү мечитиңиз.",
  "zakat_faq_title": "Көп берилүүчү суроолор",
  "zakat_guide_title": "Кыргызстанда закят боюнча толук колдонмо 2026",
  "zakat_guide_intro": "Закят - милдеттүү садака (таза активдердин 2.5%и), исламдын беш тиреӨӨлөрүнүн бири. Нисабга (байлык босогосу) жеткенде жыл сайын төлөнөт.",
  "zakat_faq_q1": "Нисаб деген эмне?",
  "zakat_faq_a1": "Нисаб - закят милдеттүү болгон байлыктын минималдуу чеги. 2026-жылы 85 г алтын же 595 г күмүштүн эквиваленти. Сомдо болжол менен 250,000-300,000 сом.",
  "zakat_faq_q2": "Кайсы активдерден закят төлөнөт?",
  "zakat_faq_a2": "Акча, алтын, күмүш, соода товарлары, акциялар, айыл чарба продукциясы. Жеке турак үйдөн, үй-бүлө үчүн унаадан, иш куралдарынан төлөнбөйт.",
  "zakat_faq_q3": "Закятты кантип эсептөө керек?",
  "zakat_faq_a3": "Бардык активдерди (накт + салымдар + алтын + товарлар) кошуңуз, карыздарды алып салыңыз. Эгер сумма > нисабдан, таза активдердин 2.5%ин төлөңүз.",
  "zakat_faq_q4": "Закятты кайда берүү керек?",
  "zakat_faq_a4": "Муктаж мусулмандарга, жетимдерге, карыздарларга, жолоочуларга, Аллахтын жолунда. КРда ДУМК, мечиттер аркылуу же муктаждарга түздөн-түз берсеңиз болот.",
