  "alimony_not_legal_advice": "<strong>Бул калькулятор юридикалык кеңешти алмаштырбайт.</strong> Эсептөө багыттоочу жана алименттердин өлчөмүнө таасир этүүчү бардык факторлорду эске албашы мүмкүн.",
