  "alimony_guide_title": "Кыргызстанда алименттер боюнча толук колдонмо 2026",
  "alimony_guide_intro": "Алименттер - КРнын Үй-бүлө кодексине ылайык балдарды камсыз кылуу үчүн милдеттүү төлөмдөр. Өлчөмү ата-эненин кирешесине жана балдардын санына жараша болот: биринчиге 25%, экөөгө 33%, үчөөгө жана андан көп балдарга 50%.",
  "alimony_faq_q1": "Алиментке кантип кайрылуу керек?",
  "alimony_faq_a1": "Баланын же жооптуучунун жашаган жерине жараша сотко арыз бериңиз. Документтер: туулгандык күбөлүк, киреше жөнүндө справка, некеге турушуу/ажырашуу жөнүндө күбөлүк. Мамлекеттик бож төлөнбөйт.",
  "alimony_faq_q2": "Атасы жумушсуз болсо эмне кылуу керек?",
  "alimony_faq_a2": "Алименттер жашаган аймактын орточо айлык акысынан эсептелет. 2026-жылы Кыргызстан боюнча - болжол менен 25,000-30,000 сом.",
  "alimony_faq_q3": "Өлчөмүн өзгөртүүгө болобу?",
  "alimony_faq_a3": "Ооба, жагдайлар өзгөргөндө (кирешенин өсүшү/төмөндөшү, башка камкордоочулардын пайда болушу, баланын оорусу ж.б.) сот аркылуу.",
  "alimony_faq_q4": "Төлөбөсө эмне кылуу керек?",
  "alimony_faq_a4": "Сот аткаруучуларына кайрылыңыз. Чаралар: счеттерди камоо, чет өлкөгө чыгууга тыюу салуу, укуктардан ажыратуу. Карыз акыркы 3 жылга өндүрүлөт.",
  "alimony_tip_1": "Балага кеткен чыгымдардын бардык чектерин жана ырастамаларын сактаңыз",
  "alimony_tip_2": "Төлөбөсө 3+ ай - дароо аткаруучуларга",
  "alimony_tip_3": "Алиментти ата-энеси төлөбөсө, чоң ата-энелерден да талап кылууга болот",
