  "currency_chart_select": "Көрсөтүү үчүн валютаны тандаңыз",
  "currency_info_note": "Курстар КР УБнын маалыматтары боюнча күн сайын жаңыртылат. Актуалдуу",
  "money_transfer_title": "Акча которуу калькулятору",
  "money_transfer_description": "Кыргызстанга акча которуу системаларын салыштыруу: Koronapay, Golden Crown, Contact, Unistream. Комиссияны эсептеп, пайдалуу которууну тандаңыз.",
  "money_transfer_subtitle": "Акча которуу системаларынын комиссияларын жана курстарын салыштырыңыз. Кыргызстанга акча жөнөтүүнүн эң пайдалуу жолун тандаңыз.",
