  "money_transfer_receive": "Алуучу алат",
  "money_transfer_guide_title": "Акча которуу системасын кантип тандоо керек",
  "money_transfer_guide_subtitle1": "Которуунун наркына эмне таасир этет",
  "money_transfer_guide_text1": "Которуунун жалпы наркы үч компоненттен турат: системанын комиссиясы (суммадан 1-3%), валюта алмаштыруу курсуна кошумча баа (1-3%) жана кошумча төлөмдөр. Бардык системаларды бир эле учурда салыштыруу үчүн биздин калькуляторду колдонуңуз.",
  "money_transfer_guide_subtitle2": "КРда популярдуу которуу системалары",
  "money_transfer_guide_text2": "Koronapay — кеңири чыгуу пункттарынын тармагы бар эң популярдуу система. Golden Crown жана Contact — чоң лимиттери бар ишенимдүү системалар. Unistream — тез которуулар. Western Union жана MoneyGram — алыскы өлкөлөрдөн которуулар үчүн эл аралык системалар.",
  "money_transfer_guide_subtitle3": "Которууларда үнөмдөө боюнча кеңештер",
  "money_transfer_guide_text3": "Комиссияны гана эмес, алмаштыруу курсун да салыштырыңыз — көбүнчө негизги айырма ошол жерде жашыруун. Чоң суммалар үчүн төмөн пайыздык ставка бар системаларды тандаңыз. Которуу системаларынын акцияларын жана промокоддорун текшериңиз. Банк картасына которуулар адатта накт акча менен берүүдөн арзанга түшөт.",
  "mobile_tariffs_title": "Мобилдик тарифтер калькулятору",
