  "mobile_tariffs_guide_subtitle1": "Керектөөңүздү баалаңыз",
  "mobile_tariffs_guide_text1": "Акыркы 3 айдын ичинде оператордун тиркемесинде колдонуу статистикасын текшериңиз. Мүнөттөрдүн, SMS жана интернеттин орточо чыгымын караңыз. Ашыкча төлөбөө үчүн 20-30% запас кошуңуз. Аз чалсаңыз — интернетке басым жасаган тарифтерди тандаңыз.",
  "mobile_tariffs_guide_subtitle2": "Кыргызстандын операторлорун салыштыруу",
  "mobile_tariffs_guide_text2": "MegaCom — эң жакшы жабуусу бар (98%) эң чоң оператор, аймактар үчүн оптималдуу. Beeline — шаарларда күчтүү 4G+, пайдалуу үй-бүлөлүк пакеттер. O! — агрессивдүү баалары бар жаш оператор, студенттер жана жаштар үчүн жакшы. Бардык операторлор соцтармактарга чексиз сунушташат.",
  "mobile_tariffs_guide_subtitle3": "Үнөмдөө боюнча кеңештер",
  "mobile_tariffs_guide_text3": "Чексиз дайыма пайдалуу эмес — чыгымыңызды эсептеңиз. Операторлордун акцияларын, айрыкча майрамдарда ээрчиңиз. Үй-бүлөлүк тарифтер 15-20% арзандатуу берет. Бонустар үчүн тарифтин автоузартуусун кошуңуз. Мобилдик интернетти үнөмдөө үчүн үйдө жана жумушта Wi-Fi колдонуңуз. Тиркемелердин фон жаңыртууну өчүрүңүз.",
