  "fuel_saving_tip_1": "Жумшак ылдамдоо жана тормоздоо — кескин старттар жана токтоолор чыгымды 20-30%га көбөйтөт.",
  "fuel_saving_tip_2": "Дөңгөлөктөгү басымды көзөмөлдөңүз — 0.5 атмга төмөн басым чыгымды 5-10%га көбөйтөт.",
  "fuel_saving_tip_3": "Ашыкча жүктү алып салыңыз — ар бир 50 кг ашык салмак чыгымды +2% көбөйтөт.",
  "fuel_saving_tip_4": "Ылдамдыкта терезелерди жабыңыз — ачык терезе аэродинамикалык каршылыкты көбөйтөт (+5% чыгым).",
  "fuel_saving_tip_5": "Регулярдуу ТО — кир аба чыпкасы чыгымды +10-15% көбөйтөт, эски свечалар +5-10%.",
  "fuel_saving_tip_6": "Круиз-контролду колдонуңуз — туруктуу ылдамдык 10% чейин үнөмдөйт.",
  "fuel_saving_tip_7": "Чатырга багажник тагып жүрбөңүз — аба каршылыгынан чыгым +10-15% көбөйөт.",
  "fuel_saving_tip_8": "Кыймылдаткыч күйүп турган бош туруудан качыңыз — бош жүрүш саатына 1-2 литр керектейт.",
  "fuel_saving_tip_9": "Газга өтүңүз — бензинге караганда дээрлик 2 эсе арзан, 1-2 жылда акталат.",
  "fuel_saving_tip_10": "Маршруттарды пландаңыз — тыгындардан качыңыз, оптималдуу жолдорду тандаңыз.",
