  "salary_article_rule_81_desc": "Стандарттык 10% ставкасында таза айлык акы эсептелгендин болжол менен 81%ын түзөт. 5% жеңилдетилген ставкада (ЖТП) — болжол менен 85.5%.",
  "salary_article_mrot_intro": "Кыргызстанда 2026-жылдын 1-январынан тартып эмгек акынын минималдуу өлчөмү (МАА) түзөт",
