  "salary_article_mrot_1": "Иш берүүчү толук ставка үчүн МААдан аз төлөй албайт (8 саат, жумасына 40 саат)",
  "salary_article_mrot_2": "МАА социалдык төлөмдөрдү, айып пулдарды, жөлөкпулдарды эсептөө үчүн колдонулат",
