  "electricity_calc_how_title": "Электр энергиясынын баасы кантип эсептелет",
  "electricity_calc_how_intro": "Кыргызстанда калк үчүн эки баскычтуу тариф колдонулат. Айына 700 кВт·чке чейин базалык ставка боюнча төлөйсүз, андан ашыгы — жогорулатылган тариф боюнча. Конкреттүү мисалда карап көрөлү.",
