  "electricity_reduce_costs_title": "Электр энергиясына чыгымды кантип азайтуу керек",
  "electricity_reduce_costs_intro": "Электр энергиясы — коммуналдык чыгымдардын эң чоң статьяларынын бири, айрыкча кышында электр менен жылытууда. Бул текшерилген үнөмдөө жолдору:",
  "electricity_led_title": "Лампаларды LEDге алмаштыруу",
  "electricity_led_text": "LED-лампа кадимки лампага караганда 8-10 эсе аз энергия керектейт. 100 Вт 10 лампаны 12 Вт LED лампаларга алмаштыруу саатына 880 Вт үнөмдөйт. Күнүнө 5 саат иштесе, айына ~132 кВт·ч — болжол менен 180 сом үнөм.",
  "electricity_efficient_tech_title": "Энергия үнөмдүү техника",
  "electricity_efficient_tech_text": "Муздаткыч, кир жуугуч машина же кондиционер сатып аларда A++ же A+++ классын тандаңыз. A жана D класстарынын ортосундагы керектөө айырмасы 40-60% болушу мүмкүн.",
  "electricity_insulation_title": "Турак жайды жылуулатуу",
  "electricity_insulation_text": "Эгер электр менен жылынсаңыз, терезелерди жана дубалдарды жылуулатуу жылуулук жоготууну 30-50%га азайтат. Бул Бишкектеги жана аймактардагы жеке үйлөр үчүн өзгөчө актуалдуу.",
  "electricity_multi_tariff_title": "Көп тарифтүү эсептегич",
  "electricity_multi_tariff_text": "КРнын айрым аймактарында түнкү тарифтүү эки зоналуу эсептегич коюуга болот. Түнкүсүн кир жуу жана түзмөктөрдү заряддоо чыгымдарды 20-30%га азайтышы мүмкүн.",
  "electricity_meters_payment_title": "Көрсөткүчтөрдү берүү жана төлөм",
  "electricity_meters_payment_intro": "Туура эсептөө үчүн электр эсептегичтин көрсөткүчтөрүн өз убагында берүү маанилүү.",
  "electricity_meter_deadline_title": "Көрсөткүчтөрдү берүү мөөнөтү",
  "electricity_meter_deadline_text": "Эсептегичтин көрсөткүчтөрүн ар айдын 23-25-күндөрү берүү керек. Көрсөткүчтөр берилбесе, акыркы 3 айдын орточо керектөөсү боюнча эсептелет.",
  "electricity_payment_methods_title": "Төлөм ыкмалары",
  "electricity_payment_methods_text": "Электр энергиясы үчүн Элсом, О!Деньги, Баланс.кг, банк тиркемелери (Оптима, Бакай, Демир Банк) аркылуу, ошондой эле «Северэлектро» же «Ошэлектро» кассаларында төлөсө болот.",
  "electricity_penalties_title": "Төлөбөгөн үчүн айыптар",
  "electricity_penalties_text": "2 айдан ашык карызы болсо, энергия менен камсыздоо уюму электр энергиясын өчүрүүгө укуктуу. Кайра туташтыруу үчүн акы алынат. Ошондой эле мөөнөтү өтүп кеткен ар бир күн үчүн пеня чегерилет.",
  "electricity_faq_q7": "Эсептегич бузулса эмне кылуу керек?",
  "electricity_faq_a7": "Электр эсептегич бузулса, 3 күндүн ичинде энергия менен камсыздоо компаниясына (Северэлектро, Ошэлектро ж.б.) кабарлоо керек. Эсептегич алмашкыча акыркы 6 айдагы орточо айлык керектөө боюнча чегерилет. Эсептегичти алмаштыруу абоненттин эсебинен жүргүзүлөт, баасы моделге жараша 1,500ден 4,000 сомго чейин.",
  "electricity_faq_q8": "Жеңилдетилген тариф ала аламбы?",
  "electricity_faq_a8": "Жеңилдетилген тариф (700 кВт·чке чейин 0.50 сом/кВт·ч) мамлекеттик «үй-бүлөгө көмөк» жөлөк пулун алган үй-бүлөлөргө берилет. Расмийлөштүрүү үчүн жөлөк пул алуучу статусун ырастаган документтер менен аймактык социалдык коргоо башкармалыгына кайрылуу керек.",
  "electricity_faq_q9": "Эмне үчүн кышында электр энергиясы үчүн эсеп кескин өсөт?",
  "electricity_faq_a9": "Кышында жарык күндүн кыскаруусу (жарыктандыруу узагыраак иштейт) жана электр жылыткычтарды колдонуу себебинен электр энергиясынын керектөөсү көбөйөт. 2 кВт кубаттуулуктагы бир майлуу жылыткыч күнүнө 10 саат иштесе, айына ~600 кВт·ч керектейт — бул 700 кВт·ч лимитке батасызбы, жокпу, ага жараша болжол менен 822-1,560 сом.",
