  "deposit_faq_a1": "Сомдо: жылына 10-14%. Долларда: 3-6%. Суммасына (10,000 сомдон) жана мөөнөтүнө (3 ай - 3 жыл) көз каранды. Ставкалар ар айда өзгөрөт.",
