  "deposit_faq_a2": "Ооба, 200,000 сомго чейин (2026-жылдан баштап). Банк банкроттук болсо — ФОЗЗ 200,000 сомго чейин кайтарат. 200,000 сомдон жогору — жоготуу коркунучу.",
