  "vehicle_tax_faq_a1": "Кыймылдаткычтын көлөмүнө көз каранды. 1.5лге чейин — 800 сом/жыл. 1.5-2.0л — 1,200 сом/жыл. 2.0-2.5л — 1,800 сом/жыл. 2.5лден жогору — 3,000+ сом/жыл.",
