  "sick_faq_q1": "Кыргызстанда оору баракчаны ким төлөйт?",
  "sick_faq_a1": "Оору баракчаны иш берүүчү КРнын Социалдык фондусунун каражаттарынан төлөйт. Иш берүүчү эсептөө жасайт, анан Соцфонддон компенсация алат. Бул иш берүүчү Соцфондго төлөмдөрдү жасабаса — оору баракча төлөнбөйт дегенди билдирет.",
  "sick_faq_q2": "Оору баракча салык менен салыкка тартылабы?",
  "sick_faq_a2": "Ооба, оору баракчалар 10% киреше салыгы менен салыкка тартылат. Эсептелген суммадан 10% алынып, силер колго 90% аласыңар. Бул КРнын Салык кодексинин милдеттүү талабы.",
  "sick_faq_q3": "Расмий эмес иштесе оору баракча алсак болобу?",
  "sick_faq_a3": "Жок. Эгер сиз расмий эмес иштесеңиз («конверттен»), иш берүүчү Социалдык фондго төлөмдөрдү жасабайт. Төлөмдөрсүз оору баракча төлөнбөйт. Бул расмий иштөөнүн маанилүү себептеринин бири.",
  "sick_faq_q4": "Канча күн оору баракча алсак болот?",
  "sick_faq_a4": "Оору боюнча — 30 күнгө чейин (дарыгерлик комиссия узартышы мүмкүн), жаракат боюнча — 60 күнгө чейин, баланы багуу боюнча — 14 күнгө чейин, кош бойлуулук боюнча — 126-180 күн.",
  "sick_faq_a4_intro": "Оору баракчанын түрүнө жараша:",
  "sick_faq_a4_illness": "Оору боюнча:",
  "sick_faq_a4_illness_val": "30 күнгө чейин (врачтык комиссия менен 180 күнгө чейин узартылышы мүмкүн)",
  "sick_faq_a4_injury": "Жаракат боюнча:",
