  "sick_faq_a4_child": "Баланы багуу боюнча:",
  "sick_faq_a4_child_val": "бир учурга 14 күнгө чейин",
  "sick_faq_a4_pregnancy": "Кош бойлуулук боюнча:",
  "sick_faq_a4_pregnancy_val": "126-180 күн (балдардын санына жараша)",
  "sick_faq_q5": "Маяна МЗИден төмөн болсочу?",
  "sick_faq_a5": "Эгер силердин 2 жылдагы орточо маянаңар эмгек акынын минималдуу өлчөмүнөн (МЗОТ = 2,500 сом) төмөн болсо, оору баракча МЗОТтон эсептелет. Башкача айтканда, минимумдан аз болушу мүмкүн эмес.",
  "sick_footer_title": "💊 calk.kg сайтындагы оору баракча калькулятору — оору баракча боюнча төлөмдү тез эсептөө",
  "sick_footer_desc": "Мөөнөттү жана орточо маянаны эске алуу менен оору баракчанын так суммасын 30 секундда эсептеңиз. КРнын 2026-жылдагы мыйзамдарына ылайык актуалдуу эреже лер!",
