  "scholarship_faq_q4": "Социалдык стипендияны ким ала алат?",
  "scholarship_faq_a4": "Социалдык стипендия тастыктоочу документтери бар аялуу категориядагы студенттерге дайындалат: жетимдерге, майыптыгы бар студенттерге жана аз камсыз болгон үй-бүлөлөрдөн чыккан студенттерге.",
