  "rental_vs_conclusion_text": "Бул мисалда ипотека",
  "rental_vs_conclusion_better": "пайдалуу",
  "rental_vs_conclusion_text2": ": 10 жылда силер азыраак төлөп, өз батириңизди аласыздар. Бирок 900,000 сом алгачкы төлөм керек. Эгер ал жок болсо — ижарага алууга туура келет.",
