  "rental_when_rent_4_text": "— райондорду өзгөртүп, мыкты шарттарды издесеңиз болот",
  "rental_when_rent_5": "Оңдоого чыгым жок",
  "rental_when_rent_5_text": "— чоң оңдоону ээси төлөйт",
  "rental_when_mortgage_title": "Качан ипотека ижарадан пайдалуу?",
  "rental_when_mortgage_1": "Узак мөөнөткө жашоо",
  "rental_when_mortgage_1_text": "— 5-7 жылдан ашык мөөнөттө ипотека акталат",
  "rental_when_mortgage_2": "Алгачкы төлөм бар",
  "rental_when_mortgage_2_text": "— турак жайдын наркынын 20-30%",
