  "loan_article_what_title": "Керектөө насыясы деген эмне?",
  "loan_article_what_intro": "Керектөө насыясы — товарларды же кызматтарды сатып алуу үчүн банктан кредит (күрөөсүз же кыймылсыз мүлктү/унааны күрөөгө коюп). КРда эң жайылган насыя түрү.",
  "loan_article_types_label": "Насыя түрлөрү:",
  "loan_type_consumer": "Керектөө:",
  "loan_type_consumer_desc": "18-28% жылына, 500,000 сомго чейин, мөөнөтү 5 жылга чейин. Күрөөсүз — 200,000 сомго чейин.",
  "loan_type_express": "Ыкчам:",
  "loan_type_express_desc": "1 саатта макулдашуу, бирок ставка жогору (25-35%), 100,000 сомго чейин.",
  "loan_type_secured": "Күрөө менен:",
  "loan_type_secured_desc": "Кыймылсыз мүлк же унааны күрөөгө коюп — ставка төмөн (12-18%), 2 млн сомго чейин.",
  "loan_article_formula_title": "Аннуитеттик төлөмдүн формуласы",
  "loan_formula_intro": "КРдагы көпчүлүк банктар аннуитеттик схеманы колдонот (ай сайын бирдей төлөм):",
  "loan_formula_annuity": "Төлөм = Сумма × (Ставка/12) × (1 + Ставка/12)^Айлар / ((1 + Ставка/12)^Айлар - 1)",
  "loan_formula_explanation": "Биринчи жылдары төлөмдүн негизги бөлүгү — пайыздар, аягында — негизги карыздын жабуусу.",
  "loan_article_examples_title": "Эсептөө мисалдары",
  "loan_example_1_title": "100,000 сом насыя 2 жылга (24% жылына)",
  "loan_example_1_desc": "Айлык төлөм: ~5,287 сом. Ашыкча төлөм: 26,888 сом (27%). Толук наркы: 126,888 сом.",
