  "loan_example_2_desc": "Айлык төлөм: ~11,150 сом. Ашыкча төлөм: 101,400 сом (34%). Толук наркы: 401,400 сом.",
  "loan_example_3_title": "Экспресс-насыя 50,000 сом 1 жылга (30% жылына)",
  "loan_example_3_desc": "Айлык төлөм: ~4,875 сом. Ашыкча төлөм: 8,500 сом (17%). Тез, бирок кымбат!",
  "loan_article_documents_title": "Керектүү документтер",
