  "patent_reg_step_2": "Ишмердүүлүк түрүн көрсөтүп, патенттик салык салууга арыз бериңиз",
  "patent_reg_step_3": "Патентти мөөнөткө алдын ала төлөңүз (15/30/90/180/365 күн), күбөлүктү алыңыз",
  "patent_faq_q4": "Патентте эсепти жүргүзүү керекпи?",
  "patent_faq_a4": "Жөнөкөйлөштүрүлгөн эсеп — кирешелер/чыгымдар китеби. Декларация берүү керек эмес; патент тандалган мөөнөткө алдын ала төлөнөт. Касса аппараты соодадо милдеттүү.",
  "patent_faq_q5": "Патенттен бирдиктүү салыкка өтсө болобу?",
  "patent_faq_a5": "Ооба, каалаган убакта, салык органына арыз берип. Тескери өтүү (бирдиктүүдөн патентке) жылдын башынан мүмкүн.",
  "patent_sources_label": "Булактар: КРнын Салык кодекси (363-367 ст.), КРнын МСК, 2026-жылдын январына актуалдуу",
