  "trafficfines_faq_a2": "Ооба, чечимди алган учурдан 10 күндүн ичинде. КРнын ИИМинин ЖКЖББГна даттануу жана далилдер менен (сүрөт, видео, күбөлөр) кайрылыңыз.",
  "trafficfines_faq_q3": "Төлөнбөгөн айыптар үчүн эмне болот?",
  "trafficfines_faq_a3": "Сумма 60 күндөн кийин эки эсе көбөйөт. Өлкөдөн чыгууга тыюу салуу, эсептерди камак, сот аткаруучулар аркылуу мажбурлоочу алуу болушу мүмкүн.",
  "trafficfines_faq_q4": "Айыпты бөлүп-бөлүп төлөсө болобу?",
  "trafficfines_faq_a4": "Жок, айып толук төлөнөт. Бирок сотто рассрочка сурасаболот (5,000 сомдон жогору чоң айыптарда).",
  "trafficfines_faq_q5": "Эски айыптар жоюлабы?",
  "trafficfines_faq_a5": "Эскирүү мөөнөтү — чечим чыгарылган учурдан 2 жыл. Андан кийин айып жоюлат, бирок практикада аларды активдүү алышат.",
  "trafficfines_sources_label": "Булактар: КРнын АУБ кодекси, КРнын ИИМинин ЖКЖББГсы, 2026-жылдын январына актуалдуу",
  "trafficfines_updated": "Жаңыртылды: 23-март 2026-жыл",
  "taxitax_article_what_title": "КРда такси айдоочулар үчүн салыктар",
  "taxitax_article_what_intro": "Эгер таксиде иштесеңиз (Яндекс.Такси, Namba Taxi, жеке ташуу), ЖИ катары каттануу жана салык төлөө милдеттүүсүз.",
  "taxitax_article_legal_note": "Мыйзамсыз ишкердик ишмердүүлүк үчүн айып: 10,000 сомго чейин.",
  "taxitax_options_title": "Такси үчүн салык салуу варианттары:",
  "taxitax_patent_title": "1. Патент (сунушталат)",
  "taxitax_patent_desc": "500-1,500 сом/ай (бекитилген сумма). Кирешеге көз карандысыз. Такси үчүн эң жөнөкөй вариант.",
  "taxitax_single_title": "2. Бирдиктүү салык",
  "taxitax_single_desc": "Киреше 6%. Жогорку кирешеде пайдалуу (40,000+ сом/ай).",
  "taxitax_ort_title": "3. Жалпы режим (ЖСР)",
  "taxitax_ort_desc": "10% КНС + 10% пайда салыгы. Чоң таксопарктар үчүн гана.",
  "taxitax_recommendation": "Кадимки таксистер үчүн 30,000-40,000 сом/айга чейинки кирешеде патент оптималдуу.",
  "taxitax_article_comparison_title": "Салыштыруу: патент vs бирдиктүү салык",
  "taxitax_table_income": "Айлык киреше",
  "taxitax_table_patent": "Патент (1,000 сом)",
  "taxitax_table_single": "Бирдиктүү салык (6%)",
  "taxitax_income_20k": "20,000 сом",
  "taxitax_income_20k_patent": "1,000 сом (5%)",
  "taxitax_income_20k_single": "1,200 сом (6%)",
  "taxitax_income_40k": "40,000 сом",
  "taxitax_income_40k_patent": "1,000 сом (2.5%)",
  "taxitax_income_40k_single": "2,400 сом (6%)",
  "taxitax_income_60k": "60,000 сом",
  "taxitax_income_60k_patent": "1,000 сом (1.7%)",
  "taxitax_income_60k_single": "3,600 сом (6%)",
  "taxitax_article_registration_title": "Кантип катталуу керек?",
  "taxitax_registration_intro": "Таксини катташтыруу процедурасы:",
  "taxitax_reg_step_1": "Салык органында ЖИ катары катталыңыз (1 күн, ~1,000 сом)",
  "taxitax_reg_step_2": "\"Такси\" ишмердүүлүк түрүнө патент сатып алыңыз (500-1,500 сом/ай)",
  "taxitax_reg_step_3": "Такси кызматына туташыңыз (Яндекс, Namba) — алар автоматтык түрдө 20-25% комиссия кармайт",
  "taxitax_faq_q1": "ЖИ катары катталуу керекпи?",
  "taxitax_faq_a1": "Ооба, эгер таксиде туруктуу иштесеңиз. Мыйзамсыз ишкердик ишмердүүлүк үчүн айып — 10,000 сомго чейин. ЖИни каттоо: 1 күн, ~1,000 сом.",
  "taxitax_faq_q2": "Яндекс.Такси аркылуу мыйзамдуу кантип иштөө керек?",
  "taxitax_faq_a2": "ЖИни каттаңыз, патент сатып алыңыз (500-1,500 сом/ай), Яндекс.Таксиге туташыңыз. Платформа автоматтык түрдө 20-25% комиссия кармайт.",
  "taxitax_faq_q3": "Салык төлөбөсө эмне болот?",
  "taxitax_faq_a3": "Мыйзамсыз ишкердик үчүн 3,000-10,000 сом айып. Салык органы акыркы 3 жылга салыктарды эсептеп + 10% жылына айып пул + суммадан 50% айып.",
  "taxitax_faq_q4": "Бир нече унаада иштесе болобу?",
  "taxitax_faq_a4": "Ооба, бирок патент 1 унааага берилет. Экинчи унаа үчүн — экинчи патент же бирдиктүү салыкка өтүү.",
  "taxitax_faq_q5": "Салыктарды кантип азайтса болот?",
  "taxitax_faq_a5": "Патентте сумма бекитилген. Бирдиктүү салыкта (6%) — чыгымдарды расмий тастыктаңыз (отун, оңдоо, камсыздандыруу) — алар салык базасын азайтат.",
  "taxitax_sources_label": "Булактар: КРнын Салык кодекси, КРнын МСК, агрегаторлордун тарифтери, 2026-жылдын январына актуалдуу",
  "taxitax_updated": "Жаңыртылды: 23-март 2026-жыл",
  "familybenefit_article_what_title": "КРда балалуу үй-бүлөлөргө жөлөк пулдар",
  "familybenefit_article_what_intro": "Кыргызстан мамлекети балалуу үй-бүлөлөрдү колдоо үчүн бир нече жөлөк пул түрлөрүн берет: туулганда, жакыр адамдарга, көп балалууларга, боюнда болгондо.",
  "familybenefit_article_who_eligible": "Өлкөдө туруктуу жашаган КРнын бардык жарандары жөлөк пулга укуктуу.",
  "familybenefit_amounts_title": "Жөлөк пулдардын өлчөмдөрү (2026):",
  "familybenefit_birth_benefit": "Бала туулганда",
