  "calorie_article_what_intro": "Калория — организм тамактан алган энергиянын бирдиги. Калорияларды эсептөө салмакты көзөмөлдөөгө, арыктоого же массаны көбөйтүүгө жардам берет.",
  "calorie_article_bmr_tdee_note": "BMR (базалык метаболизм) — тынчтыктагы энергия. TDEE (күндүк норма) = BMR × активдүүлүк коэффициенти.",
