  "moneytransfer_article_what_intro": "Акча которуу системалары чет өлкөдөн же КР ичинде 10-30 мүнөттө акча жөнөтүүгө мүмкүнчүлүк берет. Популярдуу: KoronaPay, Golden Crown, Contact, Western Union.",
  "moneytransfer_article_comparison_note": "Калькулятор комиссияларды жана курстарды салыштырып, эң пайдалуу вариантты тандоого жардам берет.",
