  "moneytransfer_tip_1": "Чоң суммалар үчүн (1,000 USD+) 2-3 системаны салыштырыңыз — айырма 5-10% болушу мүмкүн",
  "moneytransfer_tip_2": "Курс көбүнчө эртең менен жакшы — системалар курстарды күн башында жаңылайт",
