  "propertytax_article_what_title": "КРда кыймылсыз мүлк салыгы",
  "propertytax_article_what_intro": "Кыймылсыз мүлк салыгы — батир, үй, коммерциялык жайлардын ээлери үчүн жыл сайынкы милдеттүү төлөм. Жеңилдетилген аянттан ашкан бөлүгү үчүн төлөнөт.",
  "propertytax_article_legal_basis": "Негизи: КРнын Салык кодекси, 368-374-беренелер. Төлөө мөөнөтү: 1-сентябрга чейин.",
