  "propertytax_article_calculation_title": "Эсептөө формуласы",
  "propertytax_calculation_intro": "Салык жеңилдетилген аянттан ашкан бөлүккө гана алынат:",
  "propertytax_formula": "Салык = (Жалпы аянт - Жеңилдетилген аянт) × Ставка",
  "propertytax_formula_explanation": "Эгер батир 100 м² болсо, 20 м² үчүн төлөйсүз (100 - 80). Ставка 50-100 сом/м² → салык 1,000-2,000 сом/жыл.",
  "propertytax_article_examples_title": "Эсептөө мисалдары",
  "propertytax_example_1_title": "Бишкекте 65 м² батир",
  "propertytax_example_1_desc": "Аянт жеңилдетилген 80 м²ден төмөн — салык 0 сом. Төлөөнүн кереги жок.",
