  "propertytax_benefit_2": "I жана II топтогу майыптар — 50% жеңилдик",
  "propertytax_benefit_3": "Пенсионерлер — өзүнчө жеңилдик жок, бирок батир 80м²ге чейин болсо, салык жок",
  "propertytax_faq_q1": "Пенсионерлер кыймылсыз мүлк салыгын төлөйбү?",
  "propertytax_faq_a1": "Ооба, бирок жеңилдиктер бар. Эгер батир 80м²ге чейин болсо — төлөөнүн кереги жок. Эгер чоң болсо — ашыкча бөлүгү үчүн гана төлөнөт (мисалы, 100м² - 80м² = 20м² × ставка).",
  "propertytax_faq_q2": "Салык боюнча карызды кантип билсе болот?",
  "propertytax_faq_a2": "1) sts.gov.kg сайтындагы жеке кабинет, 2) Кыймылсыз мүлк катталган жердеги салык кызматы, 3) КРнын МСК мобилдик тиркемеси.",
  "propertytax_faq_q3": "Салыкты төлөбөсө эмне болот?",
  "propertytax_faq_a3": "Карыз суммасынан күнүнө 0.06% айып пул. 1 жылдан кийин — сот аткаруучулар аркылуу мажбурлоочу өндүрүү. Карыз кечирилбейт.",
  "propertytax_faq_q4": "Дача үчүн да салык төлөйбү?",
  "propertytax_faq_a4": "Ооба, эгер дача кыймылсыз мүлк катары катталган болсо. Дача үйү үчүн жеңилдетилген аянт 150 м².",
  "propertytax_faq_q5": "Салыкты бөлүп төлөөгө болобу?",
  "propertytax_faq_a5": "Ооба, салык кызматына арыз бериңиз. 3-6 айга чейин рассрочка берилиши мүмкүн, айып пулсуз.",
  "propertytax_sources_label": "Булактар: КРнын Салык кодекси (368-374 ст.), КРнын МСК, 2026-жылдын январына актуалдуу",
  "propertytax_updated": "Жаңыртылды: 23-март 2026-жыл",
  "singletax_article_what_title": "КРда ЖИ үчүн бирдиктүү салык",
  "singletax_article_what_intro": "Бирдиктүү салык — чакан жана орто бизнес үчүн жөнөкөйлөштүрүлгөн система. ЖИ НДС, пайда салыгы жана киреше салыгынын ордуна 4-6% төлөйт.",
  "singletax_article_who_eligible": "Жылдык айланма 8 млн сомго чейинки ЖИ үчүн жеткиликтүү.",
  "singletax_rates_by_activity": "Ишмердүүлүк түрлөрү боюнча ставкалар:",
  "singletax_turnover_note": "Айланма лимити: жылына 8 млн сомго чейин. Ашыкканда — жалпы режимге (ЖСР) өтүү.",
  "singletax_article_advantages_title": "Бирдиктүү салыктын артыкчылыктары",
  "singletax_advantages_intro": "Эмне үчүн ЖИ бирдиктүүнү тандайт:",
  "singletax_adv_1": "Жөнөкөйлүк — үч салык ордуна бирөө (КНС, пайда салыгы, киреше салыгы)",
  "singletax_adv_2": "Төмөн ставка — кирешенин 4-6% (ЖСРда 20-30% болушу мүмкүн)",
  "singletax_adv_3": "Жөнөкөйлөштүрүлгөн отчеттуулук — кварталга бир жолу декларация",
  "singletax_adv_4": "ККМ талап кылынбайт — кээ бир ишмердүүлүктө касса колдонбой иштөөгө болот",
  "singletax_article_examples_title": "Эсептөө мисалдары",
  "singletax_example_1_title": "Кийим дүкөнү, айланма 200,000 сом/ай",
  "singletax_example_1_desc": "Бирдиктүү салык (соода 4%): 200,000 × 4% = 8,000 сом/ай. ЖСРда ~30,000 сом болмок (КНС 10% + пайда салыгы 10% + бухгалтер чыгымы).",
  "singletax_example_2_title": "Чач тарач, айланма 80,000 сом/ай",
  "singletax_example_2_desc": "Бирдиктүү салык (кызмат 6%): 80,000 × 6% = 4,800 сом/ай. Жөнөкөй эсеп, минималдуу отчет.",
  "singletax_faq_q3": "Бирдиктүү салыкта КНС колдонсо болобу?",
  "singletax_faq_a3": "Жок, бирдиктүү салык төлөөчүлөр КНС төлөөчүлөр эмес. Бул демек сиз кардарларга КНС көрсөтпөйсүз жана сатып алуулар боюнча КНСти кайтарып албайсыз.",
  "singletax_faq_q4": "Бирдиктүү салыкка кантип өтсө болот?",
  "singletax_faq_a4": "Квартал башталганга чейин салык органына арыз бериңиз. Өтүү квартал башынан. Тескери өтүү (ЖСРга) — жылдын башынан гана.",
  "singletax_faq_q5": "Бирдиктүү салыкта эсеп жүргүзүү керекпи?",
  "singletax_faq_a5": "Ооба, жөнөкөйлөштүрүлгөн эсеп — кирешелер китеби. Декларация кварталга бир жолу берилет. Баштапкы документтерди сактоо милдеттүү.",
  "singletax_sources_label": "Булактар: КРнын Салык кодекси (378-383 ст.), КРнын МСК, 2026-жылдын январына актуалдуу",
