  "gas_maintenance_text": "Газ жабдууларын жыл сайын текшерүү милдеттүү. Текшерүүнүн баасы — 500ден 1,500 сомго чейин. Авариялык газ кызматын чакыруу — 104 номери боюнча акысыз.",
