  "gas_faq_a5": "Карызды «Кыргызгаз» мобилдик тиркемеси аркылуу, компаниянын сайтынан жеке эсеп менен, абоненттик бөлүмдүн телефону аркылуу, ошондой эле Элсом же О!Деньги аркылуу төлөөдө — система автоматтуу түрдө учурдагы карызды көрсөтөт.",
  "gas_faq_q6": "Батирде газ жыты сезилсе эмне кылуу керек?",
  "gas_faq_a6": "Дароо терезелерди ачыңыз, жарыкты күйгүзбөңүз жана өчүрбөңүз, электр приборлорду жана ширеңкени колдонбоңуз. Жайдан чыгып, 104 номери боюнча авариялык газ кызматын чакырыңыз. Адистер келгенге чейин кайтпаңыз.",
  "water_article_what_title": "Кыргызстанда суу тарифтери",
  "water_article_what_intro": "Суу менен камсыздоо жана канализация — милдеттүү коммуналдык кызматтар. Бишкекте \"Бишкекводоканал\" тейлейт. Орточо керектөө: адамга 3-5 м³/ай.",
  "water_article_provider_note": "Суу эсептегичин коюу нормативге караганда 30-50% үнөмдөйт.",
  "water_bishkekvodokanal": "\"Бишкекводоканал\" тарифтери (2026):",
