  "water_saving_intro": "Текшерилген ыкмалар:",
  "water_saving_tip_1": "Суу эсептегичтерин коюңуз — 30-50% үнөм",
  "water_saving_tip_2": "Агып жатканды тез оңдоңуз (1 тамчы/сек = 24 л/күн = 700 л/ай)",
  "water_saving_tip_3": "Ванна ордуна душ (50-100 литр үнөм)",
  "water_saving_tip_4": "Идиш жуугуч кол менен жууга караганда үнөмдүү (толук жүктөмдө)",
  "water_saving_tip_5": "Тиш жууп жатканда, самындап жатканда сууну өчүрүңүз",
  "water_faq_q1": "Суунун эсептегичинин көрсөткүчтөрүн кантип берсе болот?",
  "water_faq_a1": "1) vodokanal.kg жеке кабинети, 2) кыска номерге SMS, 3) Бишкекводоканал офиси, 4) төлөм кассасы аркылуу. Мөөнөт: айдын 23-28и.",
  "water_faq_q2": "Сууну кантип үнөмдөсө болот?",
  "water_faq_a2": "1) Эсептегичтерди коюңуз (30-50% үнөм), 2) Агып жатканды оңдоңуз, 3) Ванна ордуна душ, 4) Идиш жуугуч, 5) Тиш жууп жатканда сууну өчүрүү.",
  "water_faq_q3": "Суу эсептегич бузулса эмне болот?",
  "water_faq_a3": "3 күндүн ичинде Водоканалга билдирүү бериңиз. Оңдогонго чейин норматив боюнча эсептелет (6 м³/адам). Эсептегичти алмаштыруу: 1,500-2,500 сом.",
  "water_faq_q4": "Эмне үчүн суу кир болуп жатат?",
  "water_faq_a4": "Себептер: эски түтүктөр, тармакты тейлөө, авария. Водоканалга (116) даттаныңыз. Алар текшерип, оңдоого милдеттүү. Кир суу үчүн кайра эсептөөнү талап кыла аласыз.",
  "water_sources_label": "Булактар: Бишкекводоканал, тарифтер ГКЭР тарабынан бекитилген, 2026-жылдын январына актуалдуу",
