  "touristfee_faq_q1": "Туристтик жыйымды төлөө милдеттүүбү?",
  "touristfee_faq_a1": "Ооба, бул милдеттүү жергиликтүү салык. Мейманкана/пансионат жыйымды чогултууга милдеттүү. Квитанция берилет.",
  "touristfee_faq_q2": "КР жарандары төлөйбү?",
  "touristfee_faq_a2": "Ооба, КР жарандары да туристтик жыйымды төлөйт. Тиешелүү аймактын тургундары гана (прописка боюнча) бошотулат.",
  "touristfee_faq_q3": "Мейманкана квитанция бербесе эмне кылуу керек?",
  "touristfee_faq_a3": "Квитанцияны талап кылыңыз! Анысыз корголбойсуз. Мейманкана бербесе — салык кызматына же туристтик инспекцияга даттаныңыз.",
  "touristfee_faq_q4": "Booking аркылуу брондосом жыйым төлөймү?",
  "touristfee_faq_a4": "Ооба, туристтик жыйым адатта Booking баасына кирбейт. Жайгашканда жерде төлөнөт. Мейманканада алдын ала тактаңыз.",
