  "heating_reduce_reflectors_title": "Жылуулук чагылдыргыч экрандар",
  "heating_reduce_reflectors_desc": "Жылытуу радиаторунун артына фольгалуу экран орнотуу жылуулукту дубалды жылытуунун ордуна бөлмөгө багыттайт. Баасы — 100 сомдон, жылуулук үнөмдөө — 5-10%га чейин.",
