  "heating_reduce_flush_desc": "Булганган радиаторлор 30-50% начар жылытат. Сезон алдында жылытуу системасын жуу 500-1,500 сом турат, бирок жылуулук берүүнү байкаларлык жакшыртат.",
  "heating_reduce_meter_title": "Жалпы үй жылуулук эсептегичи",
  "heating_reduce_meter_desc": "Жалпы үй жылуулук эсептегичин орнотуу ченем боюнча эмес, иш жүзүндө керектелген жылуулук үчүн төлөөгө мүмкүндүк берет. Жылуу кыштарда үнөмдөө 15-25% түзүшү мүмкүн.",
  "heating_faq_a6_intro": "Жылытуу күйгүзүлгөн, бирок батареялар муздак же араң жылуу болсо:",
