  "water_meter_title": "Бишкекте суу эсептегичти орнотуу",
  "water_meter_intro": "Жеке суу эсептегичти орнотуу — чыгымдарды көзөмөлдөөнүн эң жакшы жолу. Билүү керек болгон нерселер:",
  "water_meter_cost_title": "Орнотуу баасы",
  "water_meter_cost_desc": "Суу эсептегич 800дөн 2,500 сомго чейин (өндүрүүчүгө жараша). Устанын орнотуусу — 500дөн 1,000 сомго чейин. Жалпы: 1,300-3,500 сом. 3-6 айда үнөмдөө эсебинен өзүн актайт.",
  "water_meter_verification_title": "Эсептегичти текшерүү",
  "water_meter_verification_desc": "Суу эсептегичти ар бир 4-6 жылда текшерүү керек (мөөнөт приборнун паспортунда көрсөтүлгөн). Текшерүү баасы — 300дөн 700 сомго чейин. Текшерүүсүз эсептегичтин көрсөткүчтөрү кабыл алынбайт жана ченем боюнча эсептелинет.",
  "water_meter_contact_title": "Кайда кайрылуу керек",
  "water_meter_contact_desc": "Эсептегичти орнотуу жана каттоо үчүн «Бишкексууканалына» (Бишкек үчүн) же жергиликтүү суу менен камсыздоочу уюмга кайрылыңыз. Керектүү документтер: паспорт, менчик укугу жөнүндө маалымкат, арыз.",
  "water_quality_title": "Кыргызстандагы суунун сапаты",
  "water_quality_intro": "Водопровод суусунун сапаты аймактар боюнча айырмаланат. Негизги маалыматтар:",
  "water_quality_bishkek_title": "Бишкек",
  "water_quality_bishkek_desc": "Суу жер алдындагы булактардан келет жана Борбордук Азиядагы эң жакшылардын бири деп эсептелет. Бирок эски түтүктөр сапатка таасир этиши мүмкүн. Ичүүчү суу үчүн фильтр колдонуу сунушталат.",
  "water_quality_mountain_title": "Тоолуу аймактар",
  "water_quality_mountain_desc": "Тоолуу айылдарда суу көбүнчө булактардан тазалоосуз келет. Сапаты жогору, бирок жаз мезгилинде кар эрүүдөн улам булганышы мүмкүн.",
  "water_quality_complaints_title": "Суунун сапатына даттануулар",
  "water_quality_complaints_desc": "Суунун сапаты начарласа (түсү, жыты, даамы) жергиликтүү суу каналына же Мамлекеттик санитардык-эпидемиологиялык көзөмөл борборуна кайрылыңыз.",
  "water_faq_q5": "Суу эсептегичти орнотуу милдеттүүбү?",
  "water_faq_a5": "КР мыйзамдары боюнча суу эсептегичтерин орнотуу сунушталат, бирок керектөөчүлөрдүн бардык категориялары үчүн милдеттүү эмес. Бирок эсептегичсиз ченем боюнча эсептелинет, ал адатта иш жүзүндөгү керектөөдөн кыйла жогору болот. Эсептегич орноткондо үнөмдөө 30-50% түзөт.",
  "water_faq_q6": "Суу түтүгү жарылганда эмне кылуу керек?",
  "water_faq_a6": "Үй ичиндеги түтүк жарылганда стоякты жабыңыз жана ЖКХ авариялык кызматын чакырыңыз. Бишкекте «Бишкексууканал» авариялык кызматы тогуз сутка иштейт. Магистралдык түтүктө жарылуу болсо — суу каналынын диспетчердик кызматына чалыңыз. Жалпы үй тармактарындагы авариядан келген зыянды башкаруу компаниясы компенсациялайт.",
  "zakat_category_allah_path": "Аллахтын жолунда (في سبيل الله)",
  "zakat_category_new_muslims": "Жаңы ислам кабыл алгандар (مؤلفة قلوبهم)",
