  "propertytax_payment_title": "Мүлк салыгын кайда жана кантип төлөө",
  "propertytax_payment_intro": "Мүлк салыгы жыл сайын төлөнөт. Негизги төлөө ыкмалары:",
  "propertytax_payment_online_title": "Онлайн-төлөм",
  "propertytax_payment_online_desc": "МСК порталы (sts.gov.kg), Элсом, О!Деньги, Баланс.кг мобилдик тиркемелери аркылуу, ошондой эле мобилдик банктык тиркемелер аркылуу. Төлөм үчүн ИНН (салык төлөөчүнүн жеке идентификациялык номери) керек.",
  "propertytax_payment_bank_title": "Банк бөлүмүндө",
  "propertytax_payment_bank_desc": "Бардык коммерциялык банктар КР төлөмдү кабыл алат. Паспорт жана ИНН керек. Төлөм квитанциясын жок дегенде 3 жыл сактаңыз.",
  "propertytax_payment_deadlines_title": "Мөөнөттөр жана айыптар",
  "propertytax_payment_deadlines_desc": "Салыкты учур жылдын 1-сентябрына чейин төлөш керек. Мөөнөтүн өткөрүү үчүн салык суммасынын 0.09% өлчөмүндө күн сайын айып пул эсептелинет. Узак убакыт төлөбөсө МСК карызды сот аркылуу өндүрүп алышы мүмкүн.",
  "propertytax_assessed_value_title": "Кыймылсыз мүлктүн баалоо наркы",
  "propertytax_assessed_value_intro": "Салык базар баасы боюнча эмес, баалоо наркы боюнча эсептелинет, ал адатта базар баасынан кыйла төмөн.",
  "propertytax_how_determined_title": "Баалоо наркы кантип аныкталат",
  "propertytax_how_determined_desc": "Баалоону Мамлекеттик каттоо кызматы (МКК) имараттын түрү, курулган жылы, жайгашкан жери жана аянты боюнча жүргүзөт. Баалоо наркы адатта базар баасынын 20-40% түзөт.",
  "propertytax_how_find_title": "Баалоо наркын кантип билүүгө болот",
  "propertytax_how_find_desc": "Баалоо наркы кыймылсыз мүлктүн Техникалык паспортунда көрсөтүлгөн. Ошондой эле МККдан же darek.kg порталы аркылуу маалымкат алса болот. Маалымкат баасы — 200 сомдон.",
  "propertytax_disagree_title": "Баалоого макул эмес болсоңуз",
  "propertytax_disagree_desc": "Эгер баалоо наркы ашыкча деп эсептесеңиз, МККга кайра карап чыгуу жөнүндө арыз менен кайрылса болот. Зарыл болсо көз карандысыз баалоочу тартылат (кызмат баасы — 3,000 сомдон).",
  "propertytax_faq_q6": "Ипотека менен сатылып алынган кыймылсыз мүлк үчүн салык төлөш керекпи?",
  "propertytax_faq_a6": "Ооба, мүлк салыгы кыймылсыз мүлк накталай же ипотека менен сатылып алынганына карабастан менчик ээси тарабынан төлөнөт. МККда менчик укугу катталган учурдан баштап салык төлөөгө милдеттүүсүз. Ипотекалык кредит мүлк салыгынан бошотпойт.",
  "propertytax_faq_q7": "Үлүштүк менчикте салык кантип эсептелинет?",
  "propertytax_faq_a7": "Үлүштүк менчикте салык менчик ээлеринин арасында алардын үлүштөрүнө пропорционалдуу бөлүштүрүлөт. Мисалы, 80 м² батир эки менчик ээсине тең үлүштө таандык болсо, ар бири 40 м²ден салык төлөйт (ар бир менчик ээсинин салык салынбаган аянтын алып салуу — 20 м², жыйынтыгында ар бири 20 м²ден төлөйт).",

  "pension_detailed_examples_title": "Пенсияны толук эсептөө — мисалдар",
  "pension_detailed_examples_intro": "Кыргызстанда пенсия бир нече бөлүктөн турат: базалык, камсыздандыруу (1996-жылга чейинки стаж боюнча) жана топтомдоо (1996-жылдан кийинки салымдар боюнча). Типтүү учурларды карап чыгалы.",
  "pension_example1_subtitle": "Мисал 1: Эркек, 63 жаш, 35 жыл стаж",
  "pension_base_part_label": "Базалык бөлүк",
  "pension_example1_base": "~3,000 сом (мамлекет тарабынан белгиленет)",
