  "pension_example1_pre96_years": "1996-жылга чейинки стаж: 7 жыл",
  "pension_example1_avg_salary": "Орточо айлык акы: 4,000 сом (кайра эсептелген)",
  "pension_example1_replacement": "Алмаштыруу коэффициенти: 65% + (7-25) × 1% = 65% (минимум)",
  "pension_funded_part_label": "Топтомдоо бөлүгү (1996-ж. кийинки салымдар)",
  "pension_example1_contributions": "28 жылдагы салымдардын жалпы суммасы: ~840,000 сом",
